import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }


    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        boolean[] alive = new boolean[n];
        Arrays.fill(alive, true);
        // Per value: a min-heap of the original indices of the live items holding it.
        HashMap<Long, PriorityQueue<Integer>> groups = new HashMap<>();
        for (int i = 0; i < n; i++) groups.computeIfAbsent(a[i], v -> new PriorityQueue<>()).add(i);
        // Max-heap of values that (may) occur at least twice; stale entries are skipped lazily.
        PriorityQueue<Long> heap = new PriorityQueue<>(Collections.reverseOrder());
        for (Map.Entry<Long, PriorityQueue<Integer>> e : groups.entrySet())
            if (e.getValue().size() >= 2 && e.getKey() > 0) heap.add(e.getKey());
        while (!heap.isEmpty()) {
            long p = heap.poll();
            PriorityQueue<Integer> ids = groups.get(p);
            if (ids.size() < 2) continue;
            int first = ids.poll(), second = ids.poll();
            alive[first] = false;
            a[second] = p / 2;
            if (ids.size() >= 2) heap.add(p);
            long q = p / 2;
            PriorityQueue<Integer> target = groups.computeIfAbsent(q, v -> new PriorityQueue<>());
            target.add(second);
            if (q > 0 && target.size() >= 2) heap.add(q);
        }
        StringBuilder values = new StringBuilder();
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (!alive[i]) continue;
            if (count++ > 0) values.append(' ');
            values.append(a[i]);
        }
        System.out.print(count + "\n" + values + "\n");
    }
}

