import (
	"bufio"
	"container/heap"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

type minHeap []int

func (h minHeap) Len() int           { return len(h) }
func (h minHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h minHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *minHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

type maxHeap []int64

func (h maxHeap) Len() int           { return len(h) }
func (h maxHeap) Less(i, j int) bool { return h[i] > h[j] }
func (h maxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *maxHeap) Push(x any)        { *h = append(*h, x.(int64)) }
func (h *maxHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	alive := make([]bool, n)
	// Per value: a min-heap of the original indices of the live items holding it
	// (indices are appended in increasing order, which is already a valid heap).
	groups := map[int64]*minHeap{}
	for i, v := range a {
		alive[i] = true
		if groups[v] == nil {
			groups[v] = &minHeap{}
		}
		*groups[v] = append(*groups[v], i)
	}
	// Max-heap of values that (may) occur at least twice; stale entries are skipped lazily.
	values := &maxHeap{}
	for v, ids := range groups {
		if ids.Len() >= 2 && v > 0 {
			*values = append(*values, v)
		}
	}
	heap.Init(values)
	for values.Len() > 0 {
		p := heap.Pop(values).(int64)
		ids := groups[p]
		if ids.Len() < 2 {
			continue
		}
		first := heap.Pop(ids).(int)
		second := heap.Pop(ids).(int)
		alive[first] = false
		a[second] = p / 2
		if ids.Len() >= 2 {
			heap.Push(values, p)
		}
		q := p / 2
		if groups[q] == nil {
			groups[q] = &minHeap{}
		}
		target := groups[q]
		heap.Push(target, second)
		if q > 0 && target.Len() >= 2 {
			heap.Push(values, q)
		}
	}
	var body []byte
	count := 0
	for i := 0; i < n; i++ {
		if !alive[i] {
			continue
		}
		if count > 0 {
			body = append(body, ' ')
		}
		count++
		body = strconv.AppendInt(body, a[i], 10)
	}
	out := strconv.AppendInt(nil, int64(count), 10)
	out = append(out, '\n')
	out = append(out, body...)
	out = append(out, '\n')
	os.Stdout.Write(out)
}
